:root {
  --background-default: oklch(1 0 0);
  --background-subtle: oklch(0.985 0 0);
  --background-overlay: oklch(1 0 0);
  --foreground-default: oklch(0.145 0 0);
  --foreground-muted: oklch(0.556 0 0);
  --foreground-inverted: oklch(1 0 0);
  --primary-DEFAULT: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary-DEFAULT: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --destructive-DEFAULT: oklch(0.637 0.237 25.331);
  --destructive-foreground: oklch(1 0 0);
  --border-default: oklch(0.922 0 0);
  --border-input: oklch(0.922 0 0);
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.625rem;
  --radius-full: 9999px;
}
